import{_ as a,o as i,c as s,a2 as l}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Explicación Detallada del Sistema de Regulación de la Ley Espacial","description":"","frontmatter":{},"headers":[],"relativePath":"es/0013-空间法理调度体系详解.md","filePath":"es/0013-空间法理调度体系详解.md"}'),o={name:"es/0013-空间法理调度体系详解.md"};function n(c,e,t,d,r,p){return i(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="explicacion-detallada-del-sistema-de-regulacion-de-la-ley-espacial" tabindex="-1">Explicación Detallada del Sistema de Regulación de la Ley Espacial <a class="header-anchor" href="#explicacion-detallada-del-sistema-de-regulacion-de-la-ley-espacial" aria-label="Permalink to &quot;Explicación Detallada del Sistema de Regulación de la Ley Espacial&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>13</td></tr><tr><td>Módulo</td><td>Leyes Cósmicas y Sistemas de Cultivo</td></tr><tr><td>Palabras clave</td><td>Ley Espacial, Regulación de Leyes, Travesía de Planos, Espacio de Aislamiento, Tres Fundamentos del Origen</td></tr></tbody></table><h2 id="i-resumen-del-sistema" tabindex="-1">I. Resumen del Sistema <a class="header-anchor" href="#i-resumen-del-sistema" aria-label="Permalink to &quot;I. Resumen del Sistema&quot;">​</a></h2><p>El Sistema de Regulación de la Ley Espacial es el Sistema n.º 3 de los Trescientos Sistemas de Cultivo del Origen, el tercero de los &quot;Tres Fundamentos del Origen&quot;, y es el fundamento de todos los sistemas de cultivo y aplicaciones tecnológicas que implican espacio, dimensiones y operaciones de planos. Este sistema toma &quot;la comprensión y regulación de las leyes espaciales&quot; como núcleo, enfatizando la cognición precisa y la manipulación ordenada de las leyes espaciales, en lugar del desgarro y la destrucción espacial simples y brutales. El Sistema de Regulación de la Ley Espacial es el fundamento de cultivo para aplicaciones importantes como la interacción entre planos, la construcción del Espacio de Aislamiento, la tecnología del Espejo de Réplica y el mantenimiento de anclas, desempeñando un papel insustituible en la construcción de infraestructuras de la civilización simbiótica.</p><p>El Sistema de Regulación de la Ley Espacial es adecuado para cultivadores con fuerte percepción espacial, pensamiento lógico meticuloso y enfoque en la precisión y el orden. Los cultivadores de este sistema son el grupo de talentos técnicos más importante de la civilización simbiótica, asumiendo tareas clave como la construcción de anclas, el mantenimiento de canales entre planos, la gestión del Espacio de Aislamiento y la construcción de espacios arqueológicos.</p><h2 id="ii-principios-centrales-del-sistema" tabindex="-1">II. Principios Centrales del Sistema <a class="header-anchor" href="#ii-principios-centrales-del-sistema" aria-label="Permalink to &quot;II. Principios Centrales del Sistema&quot;">​</a></h2><p>El principio central del Sistema de Regulación de la Ley Espacial es &quot;el espacio es ley, la regulación es orden&quot;, comprensible desde los siguientes tres niveles:</p><h3 id="_2-1-la-esencia-legal-del-espacio" tabindex="-1">2.1 La Esencia Legal del Espacio <a class="header-anchor" href="#_2-1-la-esencia-legal-del-espacio" aria-label="Permalink to &quot;2.1 La Esencia Legal del Espacio&quot;">​</a></h3><p>En la visión cósmica de Heng Yuan Zhou, el espacio no es un contenedor vacío, sino una estructura ordenada compuesta por una serie de reglas legales. Los atributos del espacio — dimensiones, distancia, dirección, curvatura, estabilidad, etc. — están todos determinados por las reglas legales espaciales subyacentes. Comprender la esencia del espacio es comprender los mecanismos de funcionamiento de estas reglas legales.</p><p>Las leyes espaciales pueden dividirse en tres niveles: leyes fundamentales (que determinan los atributos básicos del espacio, como la estructura tridimensional, la definición de distancia, etc.), leyes de transformación (que determinan la variabilidad del espacio, como el plegado espacial, los cambios de curvatura, etc.) y leyes del Origen (que determinan la creación y destrucción del espacio, como la formación y el colapso de los planos). El cultivo del Sistema de Regulación de la Ley Espacial comienza por la comprensión de las leyes fundamentales, profundizando gradualmente hacia las leyes de transformación y del Origen.</p><h3 id="_2-2-el-metodo-central-de-la-regulacion" tabindex="-1">2.2 El Método Central de la Regulación <a class="header-anchor" href="#_2-2-el-metodo-central-de-la-regulacion" aria-label="Permalink to &quot;2.2 El Método Central de la Regulación&quot;">​</a></h3><p>La &quot;regulación&quot; es la metodología central del Sistema de Regulación de la Ley Espacial. A diferencia del &quot;desgarro espacial&quot; del cultivo depredador, la regulación no usa la violencia para destruir estructuras espaciales, sino que logra un ajuste y manipulación ordenados del espacio comprendiendo y siguiendo las leyes espaciales.</p><p>Los métodos centrales de la regulación incluyen:</p><ul><li><strong>Percepción de leyes</strong>: percibir el estado de funcionamiento de las reglas legales en el espacio, identificando estructuras y anomalías espaciales</li><li><strong>Guía de leyes</strong>: guiar las leyes espaciales para que funcionen en la dirección esperada mediante la propia energía y conciencia</li><li><strong>Resonancia de leyes</strong>: resonar con las leyes espaciales, amplificando el efecto y el alcance de la regulación</li><li><strong>Solidificación de leyes</strong>: solidificar los resultados de la regulación en estructuras espaciales estables, como el Espacio de Aislamiento, los canales entre planos, etc.</li></ul><p>La clave de la regulación es &quot;seguir el impulso&quot;. El cultivador no es el amo del espacio, sino el &quot;regulador&quot; de las leyes espaciales — logrando una manipulación ordenada del espacio mediante la comprensión y el seguimiento de las leyes.</p><h3 id="_2-3-principios-eticos-de-las-operaciones-espaciales" tabindex="-1">2.3 Principios Éticos de las Operaciones Espaciales <a class="header-anchor" href="#_2-3-principios-eticos-de-las-operaciones-espaciales" aria-label="Permalink to &quot;2.3 Principios Éticos de las Operaciones Espaciales&quot;">​</a></h3><p>El Sistema de Regulación de la Ley Espacial establece estrictos principios éticos para las operaciones espaciales:</p><ul><li><strong>Principio de Intervención Mínima</strong>: las operaciones sobre el espacio deben ser lo más pequeñas posible, evitando la destrucción innecesaria de estructuras espaciales</li><li><strong>Principio de Recuperabilidad</strong>: todas las operaciones espaciales temporales deben restaurar el espacio a su estado original tras su finalización, sin dejar daños permanentes</li><li><strong>Principio de Aislamiento</strong>: las operaciones espaciales que puedan producir riesgos deben realizarse en el Espacio de Aislamiento, evitando la propagación de riesgos</li><li><strong>Principio de Aprobación</strong>: las operaciones espaciales avanzadas (como la travesía de planos, el plegado espacial, etc.) deben ser aprobadas por las instituciones de gestión de anclas</li></ul><h2 id="iii-division-de-niveles-y-caracteristicas-de-cada-etapa" tabindex="-1">III. División de Niveles y Características de Cada Etapa <a class="header-anchor" href="#iii-division-de-niveles-y-caracteristicas-de-cada-etapa" aria-label="Permalink to &quot;III. División de Niveles y Características de Cada Etapa&quot;">​</a></h2><p>El Sistema de Regulación de la Ley Espacial se divide en cinco niveles centrales:</p><table tabindex="0"><thead><tr><th>Nivel</th><th>Nombre</th><th>Características Centrales</th><th>Alcance de Manipulación Espacial</th><th>Capacidad Característica</th></tr></thead><tbody><tr><td>Primer nivel</td><td>Reconocimiento del Espacio</td><td>Percibir preliminarmente la existencia de las leyes espaciales, capaz de identificar la estructura básica del espacio</td><td>Alcance de percepción: cien metros</td><td>Percepción Espacial: puede percibir el estado legal y las anomalías del espacio circundante</td></tr><tr><td>Segundo nivel</td><td>Dominio del Espacio</td><td>Capaz de realizar manipulación básica del espacio, como desplazamiento espacial de corta distancia</td><td>Alcance de manipulación: diez metros</td><td>Teletransportación Corta: puede realizar desplazamiento espacial dentro de diez metros</td></tr><tr><td>Tercer nivel</td><td>Transformación del Espacio</td><td>Capaz de cambiar atributos locales del espacio, como el plegado espacial, el ajuste de curvatura</td><td>Alcance de manipulación: cien metros</td><td>Plegado Espacial: puede plegar una distancia de cien metros en un solo paso</td></tr><tr><td>Cuarto nivel</td><td>Ley del Espacio</td><td>Capaz de construir estructuras espaciales estables, como el Espacio de Aislamiento, el espacio de almacenamiento</td><td>Alcance de manipulación: kilómetros</td><td>Construcción del Espacio de Aislamiento: puede crear espacios independientes estables para cultivo o experimentos</td></tr><tr><td>Quinto nivel</td><td>Origen del Espacio</td><td>Toca las leyes del Origen del espacio, capaz de realizar travesía de planos y construcción de canales entre planos</td><td>Alcance de manipulación: entre planos</td><td>Travesía de Planos: puede realizar travesía estable entre planos con apoyo de anclas</td></tr></tbody></table><p>El avance de cada nivel requiere aprobar la &quot;Evaluación de la Ley Espacial&quot;: evaluar la profundidad de comprensión de las leyes espaciales del cultivador, la precisión y estabilidad de la manipulación espacial y el cumplimiento de la ética de operaciones espaciales; solo cuando se cumplen los tres estándares puede confirmarse la elevación del nivel.</p><h2 id="iv-metodos-centrales-de-cultivo-del-sistema" tabindex="-1">IV. Métodos Centrales de Cultivo del Sistema <a class="header-anchor" href="#iv-metodos-centrales-de-cultivo-del-sistema" aria-label="Permalink to &quot;IV. Métodos Centrales de Cultivo del Sistema&quot;">​</a></h2><h3 id="_4-1-metodos-de-cultivo-de-percepcion-de-leyes" tabindex="-1">4.1 Métodos de Cultivo de Percepción de Leyes <a class="header-anchor" href="#_4-1-metodos-de-cultivo-de-percepcion-de-leyes" aria-label="Permalink to &quot;4.1 Métodos de Cultivo de Percepción de Leyes&quot;">​</a></h3><p>La percepción de leyes es el fundamento del Sistema de Regulación de la Ley Espacial, e incluye:</p><ul><li><strong>Método de Escucha Espacial</strong>: en un espacio silencioso, cerrar los ojos y concentrarse, percibiendo el funcionamiento sutil de las leyes espaciales, como &quot;escuchar&quot; la respiración del espacio</li><li><strong>Método de Identificación de Anomalías</strong>: realizar entrenamiento de percepción en áreas que contienen anomalías espaciales (como grietas espaciales, anomalías de curvatura), mejorando la capacidad de identificar anomalías espaciales</li><li><strong>Método de Percepción Multidimensional</strong>: entrenarse gradualmente para percibir estructuras espaciales más allá de tres dimensiones, sentando las bases para comprender las leyes espaciales de alta dimensión</li><li><strong>Método del Mapa de Leyes</strong>: dibujar las estructuras legales espaciales percibidas en un &quot;mapa de leyes&quot; en la conciencia, mejorando la cognición global de las estructuras espaciales</li></ul><h3 id="_4-2-metodos-de-cultivo-de-manipulacion-espacial" tabindex="-1">4.2 Métodos de Cultivo de Manipulación Espacial <a class="header-anchor" href="#_4-2-metodos-de-cultivo-de-manipulacion-espacial" aria-label="Permalink to &quot;4.2 Métodos de Cultivo de Manipulación Espacial&quot;">​</a></h3><p>La manipulación espacial es la habilidad central del sistema, e incluye:</p><ul><li><strong>Método de Entrenamiento de Micro-Manipulación</strong>: comenzar desde el rango más pequeño de manipulación espacial, como plegar un centímetro de espacio, mejorando progresivamente la precisión y el alcance</li><li><strong>Método de Cultivo de Desplazamiento</strong>: comenzar desde el desplazamiento espacial de corta distancia, aumentando gradualmente la distancia y la complejidad, logrando finalmente la teletransportación continua</li><li><strong>Método de Cultivo de Plegado</strong>: entrenar la capacidad de plegado espacial, desde el plegado lineal simple hasta el plegado multidimensional complejo</li><li><strong>Método de Cultivo de Curvatura</strong>: entrenar la capacidad de ajustar la curvatura espacial; la manipulación de la curvatura es el fundamento de la tecnología espacial avanzada</li></ul><h3 id="_4-3-metodos-de-cultivo-de-construccion-espacial" tabindex="-1">4.3 Métodos de Cultivo de Construcción Espacial <a class="header-anchor" href="#_4-3-metodos-de-cultivo-de-construccion-espacial" aria-label="Permalink to &quot;4.3 Métodos de Cultivo de Construcción Espacial&quot;">​</a></h3><p>La construcción espacial es la habilidad avanzada del sistema, e incluye:</p><ul><li><strong>Método de Construcción de Espacio de Almacenamiento</strong>: aprender a construir pequeños espacios de almacenamiento estables, dominando la tecnología de solidificación de fronteras espaciales</li><li><strong>Método de Construcción del Espacio de Aislamiento</strong>: aprender a construir espacios independientes con efecto de aislamiento, dominando las barreras espaciales y la tecnología de aislamiento energético</li><li><strong>Método de Construcción de Espacio de Cultivo</strong>: aprender a construir espacios especiales adecuados para el cultivo, como salas de cultivo con diferente velocidad de flujo temporal, campos de cultivo con concentración energética ajustable, etc.</li><li><strong>Método de Construcción de Canales entre Planos</strong>: con apoyo de anclas, aprender a construir canales estables que conecten dos planos</li></ul><h2 id="v-aplicaciones-del-sistema-en-la-civilizacion-simbiotica" tabindex="-1">V. Aplicaciones del Sistema en la Civilización Simbiótica <a class="header-anchor" href="#v-aplicaciones-del-sistema-en-la-civilizacion-simbiotica" aria-label="Permalink to &quot;V. Aplicaciones del Sistema en la Civilización Simbiótica&quot;">​</a></h2><p>El Sistema de Regulación de la Ley Espacial tiene aplicaciones amplias e importantes en la civilización simbiótica:</p><h3 id="_5-1-construccion-de-infraestructuras" tabindex="-1">5.1 Construcción de Infraestructuras <a class="header-anchor" href="#_5-1-construccion-de-infraestructuras" aria-label="Permalink to &quot;5.1 Construcción de Infraestructuras&quot;">​</a></h3><ul><li><strong>Construcción y mantenimiento de anclas</strong>: los cultivadores avanzados del Sistema de Regulación de la Ley Espacial son la fuerza central de la construcción de anclas, responsables del diseño y construcción de las estructuras espaciales de las anclas</li><li><strong>Mantenimiento de canales entre planos</strong>: mantener los canales espaciales que conectan varios planos, asegurando la estabilidad y seguridad de los canales</li><li><strong>Construcción de espacios de cultivo públicos</strong>: construir instalaciones espaciales especiales como salas de cultivo públicas, salas de comprensión de leyes, etc.</li></ul><h3 id="_5-2-arqueologia-e-investigacion" tabindex="-1">5.2 Arqueología e Investigación <a class="header-anchor" href="#_5-2-arqueologia-e-investigacion" aria-label="Permalink to &quot;5.2 Arqueología e Investigación&quot;">​</a></h3><ul><li><strong>Arqueología remota del Espejo de Réplica</strong>: los cultivadores de Regulación de la Ley Espacial participan en la construcción espacial de la tecnología del Espejo de Réplica, proporcionando espacios remotos aislados para la arqueología</li><li><strong>Experimentos en Espacio de Aislamiento</strong>: proporcionar Espacio de Aislamiento para experimentos peligrosos con leyes y energías, evitando la propagación de riesgos</li><li><strong>Investigación de espacios antiguos</strong>: estudiar las estructuras espaciales y tecnologías espaciales dejadas por civilizaciones antiguas</li></ul><h3 id="_5-3-aplicaciones-cotidianas" tabindex="-1">5.3 Aplicaciones Cotidianas <a class="header-anchor" href="#_5-3-aplicaciones-cotidianas" aria-label="Permalink to &quot;5.3 Aplicaciones Cotidianas&quot;">​</a></h3><ul><li><strong>Tecnología de almacenamiento espacial</strong>: proporcionar utensilios de almacenamiento espacial a la gente común, facilitando la vida diaria</li><li><strong>Medicina espacial</strong>: usar tecnología espacial para operaciones médicas precisas, como cirugía no invasiva, extirpación de lesiones internas, etc.</li><li><strong>Transporte espacial</strong>: sistemas de transporte de corta distancia basados en la tecnología de plegado espacial, mejorando enormemente la eficiencia de desplazamiento</li></ul><h3 id="_5-4-seguridad-y-defensa" tabindex="-1">5.4 Seguridad y Defensa <a class="header-anchor" href="#_5-4-seguridad-y-defensa" aria-label="Permalink to &quot;5.4 Seguridad y Defensa&quot;">​</a></h3><ul><li><strong>Barreras espaciales</strong>: construir barreras espaciales para la protección de instalaciones importantes</li><li><strong>Bloqueo espacial</strong>: en emergencias, realizar bloqueo espacial de áreas específicas para evitar la propagación del peligro</li><li><strong>Rescate espacial</strong>: usar la capacidad de desplazamiento espacial para rescates de emergencia, como transferir rápidamente personas desde sitios de desastre</li></ul><h2 id="vi-ventajas-y-limitaciones-del-sistema" tabindex="-1">VI. Ventajas y Limitaciones del Sistema <a class="header-anchor" href="#vi-ventajas-y-limitaciones-del-sistema" aria-label="Permalink to &quot;VI. Ventajas y Limitaciones del Sistema&quot;">​</a></h2><h3 id="_6-1-ventajas" tabindex="-1">6.1 Ventajas <a class="header-anchor" href="#_6-1-ventajas" aria-label="Permalink to &quot;6.1 Ventajas&quot;">​</a></h3><ul><li>Valor práctico extremadamente alto; sistema central indispensable para la construcción de infraestructuras de la civilización</li><li>La capacidad de manipulación espacial tiene enormes ventajas en combate, exploración, rescate y otros escenarios</li><li>Alto estatus social de los cultivadores; ricas oportunidades de empleo y desarrollo</li><li>Integración estrecha con las aplicaciones tecnológicas; los resultados del cultivo pueden transformarse directamente en productos tecnológicos</li><li>Tras mejorar la percepción espacial, también asiste al cultivo de otros sistemas</li></ul><h3 id="_6-2-limitaciones" tabindex="-1">6.2 Limitaciones <a class="header-anchor" href="#_6-2-limitaciones" aria-label="Permalink to &quot;6.2 Limitaciones&quot;">​</a></h3><ul><li>Ciertos requisitos de talento en percepción espacial; no todas las razas son adecuadas</li><li>La capacidad de combate mejora poco en la etapa inicial; las capacidades principales se inclinan hacia la asistencia y la tecnología</li><li>Las operaciones espaciales avanzadas conllevan mayores riesgos; los errores de operación pueden causar consecuencias graves como grietas espaciales</li><li>El avance de niveles altos requiere apoyo de anclas; difícil de practicar en áreas con cobertura de anclas insuficiente</li><li>El proceso de cultivo es relativamente monótono, requiriendo mucho entrenamiento de manipulación precisa</li></ul><h2 id="vii-compatibilidad-con-otros-sistemas" tabindex="-1">VII. Compatibilidad con Otros Sistemas <a class="header-anchor" href="#vii-compatibilidad-con-otros-sistemas" aria-label="Permalink to &quot;VII. Compatibilidad con Otros Sistemas&quot;">​</a></h2><p>El Sistema de Regulación de la Ley Espacial tiene buena compatibilidad con otros sistemas, especialmente:</p><ul><li>Práctica concurrente con el Sistema de Iteración Deductiva: puede deducir varios métodos de aplicación de las leyes espaciales, mejorando la precisión e innovación de la manipulación espacial</li><li>Práctica concurrente con el Sistema de Circulación de la Vida: puede construir espacios dedicados a la circulación de la energía vital, mejorando la eficiencia del cultivo de circulación de la vida</li><li>Práctica concurrente con sistemas de ascensión de la conciencia: la comprensión de las leyes espaciales ayuda a la conciencia a percibir y adaptarse al espacio de alta dimensión</li><li>Práctica concurrente con sistemas de ingeniería de aplicación: la tecnología de leyes espaciales es una rama importante de la ingeniería de leyes; la práctica concurrente puede mejorar enormemente la capacidad de ingeniería</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El Sistema de Regulación de la Ley Espacial es la &quot;piedra angular espacial&quot; de la Civilización Simbiótica del Ancla. Basado en la profunda comprensión de las leyes espaciales y con la regulación ordenada como método, proporciona un apoyo tecnológico espacial indispensable para la interacción entre planos, la construcción de infraestructuras, la investigación científica y las aplicaciones cotidianas de la civilización. El objetivo último del Sistema de Regulación de la Ley Espacial es hacer de los cultivadores los &quot;guardianes y constructores&quot; del espacio cósmico — sobre la base de comprender las leyes espaciales, construir una red espacial cósmica más ordenada, más conectada y más segura.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Panorama de los Trescientos Sistemas de Cultivo del Origen)</li><li>62-空间法理技术实现 (Realización Tecnológica de la Ley Espacial)</li><li>64-隔离空间构建技术 (Tecnología de Construcción del Espacio de Aislamiento)</li></ul>',54)])])}const g=a(o,[["render",n]]);export{m as __pageData,g as default};
